-- 0023 — Nice Classification list of goods and services (item 26: Nice 13th edition; Section 6 group 4).
-- Source: WIPO revision file ncl-20270101 (English, French, Spanish), supplied by the Founder on 18 Nov 2026.
-- It carries two versions: NCL(13-2026), in force now, and NCL(13-2027), in force from 1 January 2027.
-- Both are loaded; each term carries the dates it is in force, so the list changes over by itself on 1 January.
-- No Arabic list is published in this file; screens fall back to English until one is loaded.
-- Generated from the spreadsheet: 10123 terms in force in 2026, 10227 from 2027 (one row per basic number and wording).
BEGIN;

CREATE TABLE registry.nice_edition (
  code          text PRIMARY KEY,
  in_force_from date NOT NULL UNIQUE,
  created_at    timestamptz NOT NULL DEFAULT now()
);
INSERT INTO registry.nice_edition (code, in_force_from) VALUES ('NCL(13-2026)', DATE '2026-01-01'), ('NCL(13-2027)', DATE '2027-01-01');
GRANT SELECT ON registry.nice_edition TO meesam_app, meesam_worker, meesam_staff, meesam_admin, meesam_readonly;

ALTER TABLE registry.nice_term
  ADD COLUMN in_force_from  date NOT NULL DEFAULT DATE '2026-01-01',
  ADD COLUMN in_force_until date NULL,                       -- first day the wording no longer applies
  ADD CONSTRAINT nice_term_basic_from UNIQUE (basic_number, in_force_from);
CREATE INDEX nice_term_class_in_force ON registry.nice_term (class_id, in_force_from, in_force_until);

-- The terms of one class in force on a date.
CREATE FUNCTION registry.fn_nice_terms(p_class smallint, p_on date DEFAULT CURRENT_DATE)
RETURNS SETOF registry.nice_term LANGUAGE sql STABLE AS $$
  SELECT t.* FROM registry.nice_term t JOIN registry.nice_class c ON c.id = t.class_id
   WHERE c.number = p_class AND t.in_force_from <= p_on AND (t.in_force_until IS NULL OR p_on < t.in_force_until)
$$;
GRANT EXECUTE ON FUNCTION registry.fn_nice_terms(smallint, date) TO meesam_app, meesam_worker, meesam_staff, meesam_admin, meesam_readonly;


